"""Static figures and an auto-generated RESULTS.md so README numbers always come from a real run."""
from __future__ import annotations

import json
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
from sklearn.inspection import permutation_importance  # noqa: E402

from src.config import Config  # noqa: E402
from src.models.evaluate import eval_subset, reliability_table  # noqa: E402


def feature_importance(models: dict, cfg: Config, features: list[str], n: int = 8000) -> pd.DataFrame:
    """Permutation importance (MAE) of the growth model on the latest *labelled* test window."""
    for k in sorted(models, reverse=True):
        model, test = models[k]
        t = test[test["y_growth"].notna() & (test["inc"] >= cfg.eval_min_incidence)]
        if len(t) >= 500:
            t = t.sample(min(n, len(t)), random_state=cfg.seed)
            # use only features the model was actually trained on (constant cols may have been dropped)
            active = getattr(model, "_active_features", features)
            r = permutation_importance(model.reg, t[active], t["y_growth"], n_repeats=5,
                                       scoring="neg_mean_absolute_error", random_state=cfg.seed)
            return (pd.DataFrame({"feature": active, "importance": r.importances_mean,
                                  "std": r.importances_std})
                    .sort_values("importance", ascending=False).reset_index(drop=True))
    return pd.DataFrame(columns=["feature", "importance", "std"])


def make_figures(pred: pd.DataFrame, metrics: dict, importance: pd.DataFrame, cfg: Config,
                 out_dir: Path) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    d = eval_subset(pred, cfg)

    # 1. model comparison
    reg = metrics["regression"]
    fig, ax = plt.subplots(figsize=(6, 3.4))
    names = list(reg)
    ax.barh(names, [reg[n]["mae"] for n in names], color=["#9aa5b1", "#9aa5b1", "#9aa5b1", "#d1495b"])
    ax.set_xlabel(f"MAE of {cfg.horizon}-day log-growth (lower is better)")
    ax.set_title("Out-of-sample error, walk-forward backtest")
    fig.tight_layout()
    fig.savefig(out_dir / "model_comparison.png", dpi=160)
    plt.close(fig)

    # 2. reliability diagram
    fig, ax = plt.subplots(figsize=(4.6, 4.4))
    ax.plot([0, 1], [0, 1], "k--", lw=1, label="perfect")
    ys = d["y_surge"].to_numpy()
    for col, lab, c in (("surge_prob_clf", "direct GBM classifier", "#9aa5b1"), ("surge_prob", "conformal distributional", "#d1495b")):
        t = reliability_table(ys, d[col].to_numpy())
        ax.plot(t["mean_pred"], t["observed"], "o-", label=lab, color=c)
    ax.set_xlabel("Predicted surge probability")
    ax.set_ylabel("Observed frequency")
    ax.set_title("Reliability of surge risk")
    ax.legend()
    fig.tight_layout()
    fig.savefig(out_dir / "reliability.png", dpi=160)
    plt.close(fig)

    # 3. permutation importance
    if len(importance):
        top = importance.head(15).iloc[::-1]
        fig, ax = plt.subplots(figsize=(6, 4.6))
        ax.barh(top["feature"], top["importance"], xerr=top["std"], color="#2e86ab")
        ax.set_xlabel("Increase in MAE when feature is permuted")
        ax.set_title("What drives the forecast?")
        fig.tight_layout()
        fig.savefig(out_dir / "feature_importance.png", dpi=160)
        plt.close(fig)

    # 4. forecast vs. truth for the four countries with most cumulative signal
    top_iso = d.groupby("iso3")["inc"].sum().nlargest(4).index.tolist()
    fig, axes = plt.subplots(2, 2, figsize=(10, 6), sharex=True)
    h = pd.Timedelta(days=cfg.horizon)
    for ax, iso in zip(axes.ravel(), top_iso):
        g = pred[pred["iso3"] == iso].sort_values("date")
        ax.plot(g["date"], g["inc"], color="#222", lw=1.2, label="observed")
        ax.plot(g["date"] + h, g["pred_inc"], color="#d1495b", lw=1.2, label=f"{cfg.horizon}-day-ahead forecast")
        ax.fill_between(g["date"] + h, g["pred_inc_lo"], g["pred_inc_hi"], color="#d1495b", alpha=0.18,
                        label="80% interval")
        ax.set_title(g["country"].iloc[0])
        ax.set_ylabel("cases / million / day")
    axes[0, 0].legend(fontsize=8)
    fig.autofmt_xdate()
    fig.tight_layout()
    fig.savefig(out_dir / "forecast_examples.png", dpi=160)
    plt.close(fig)


def write_results_md(metrics: dict, by_cont: pd.DataFrame, importance: pd.DataFrame, path: Path) -> None:
    reg, clf, iv = metrics["regression"], metrics["surge_classification"], metrics["interval"]
    g = clf["conformal_distributional"]
    lines = [
        "# Results (auto-generated by `outbreakiq run`)", "",
        f"Walk-forward backtest, {metrics['n_folds']} folds, {metrics['n_countries']} countries, "
        f"{metrics['date_range'][0]} to {metrics['date_range'][1]}, "
        f"{metrics['n_rows']:,} out-of-sample country-days, horizon {metrics['horizon_days']} days.", "",
        "## Forecast error (log-growth of incidence)", "",
        "| Model | MAE | RMSE | R² | WAPE (cases) | Skill vs persistence |", "|---|---|---|---|---|---|",
    ]
    for name, m in reg.items():
        lines.append(f"| {name} | {m['mae']:.3f} | {m['rmse']:.3f} | {m['r2']:.3f} | "
                     f"{m['wape_level']:.3f} | {m['skill_vs_persistence']:+.1%} |")
    lines += ["", f"80% prediction interval empirical coverage: **{iv['coverage']:.1%}** "
              f"(mean width {iv['mean_width_log']:.2f} log units).", "",
              "## Surge risk (calibrated probability that incidence rises ≥ "
              "the configured ratio within the horizon)", "",
              "| Score | AUROC (fold mean) | AUROC (pooled) | PR-AUC | Brier | ECE |", "|---|---|---|---|---|---|"]
    for name in ("conformal_distributional", "direct_classifier"):
        m = clf[name]
        lines.append(f"| {name} | {m['auroc_fold_mean']:.3f} | {m['auroc']:.3f} | {m['pr_auc']:.3f} | "
                     f"{m['brier']:.3f} | {m['ece']:.3f} |")
    for name in ("damped_trend_score", "ridge_score"):
        m = clf[name]
        lines.append(f"| {name} | {m['auroc_fold_mean']:.3f} | {m['auroc']:.3f} | {m['pr_auc']:.3f} | – | – |")
    lines += ["", f"Surge prevalence in the evaluation set: {metrics['surge_prevalence']:.1%}. "
              f"Brier skill vs climatology: {g['brier_skill_vs_climatology']:+.1%}.", ""]
    if len(by_cont):
        lines += ["## By continent", "", by_cont.round(3).to_markdown(index=False)
                  if _has_tabulate() else by_cont.round(3).to_string(index=False), ""]
    if len(importance):
        lines += ["## Top drivers (permutation importance)", ""]
        lines += [f"- `{r.feature}`: {r.importance:.4f}" for r in importance.head(8).itertuples()]
    Path(path).write_text("\n".join(lines) + "\n", encoding="utf-8")


def _has_tabulate() -> bool:
    try:
        import tabulate  # noqa: F401
        return True
    except ImportError:
        return False


def save_metrics(metrics: dict, path: Path) -> None:
    def default(o):
        if isinstance(o, (np.floating, np.integer)):
            return o.item()
        raise TypeError(type(o))
    Path(path).write_text(json.dumps(metrics, indent=2, default=default))
